-- ------------------------------ Vue utile -----------------------------
CREATE VIEW v_ventes AS
SELECT c.id_commande, c.date_commande, c.canal, c.statut,
       cl.id_client, cl.ville AS ville_client, cl.segment,
       p.nom_produit, ca.nom_categorie,
       l.quantite, l.prix_unitaire, l.remise,
       ROUND(l.quantite * l.prix_unitaire * (1 - l.remise), 2) AS montant_ttc
FROM lignes_commande l
JOIN commandes c   ON c.id_commande = l.id_commande
JOIN clients cl    ON cl.id_client = c.id_client
JOIN produits p    ON p.id_produit = l.id_produit
JOIN categories ca ON ca.id_categorie = p.id_categorie;

-- Vérification rapide
SELECT 'clients' AS table_name, COUNT(*) AS nb FROM clients
UNION ALL SELECT 'produits', COUNT(*) FROM produits
UNION ALL SELECT 'commandes', COUNT(*) FROM commandes
UNION ALL SELECT 'lignes_commande', COUNT(*) FROM lignes_commande;
